) as t(reg_no, company, driver_name, driver_phone, capacity_tonnes, depot_code, source_meta)
left join public.depots d on d.code = t.depot_code
on conflict (reg_no) do update set
  depot_id = coalesce(excluded.depot_id, trucks.depot_id),
  company = coalesce(excluded.company, trucks.company),
  driver_name = coalesce(excluded.driver_name, trucks.driver_name),
  driver_phone = coalesce(excluded.driver_phone, trucks.driver_phone),
  capacity_tonnes = coalesce(excluded.capacity_tonnes, trucks.capacity_tonnes),
  source_meta = trucks.source_meta || excluded.source_meta,
  updated_at = now();

-- ===== 4. TRUCK INSPECTIONS (1,619 historical logs) =====
-- Joined to trucks through source_meta->>'vehicle_id' because the
-- inspection log records VehicleID, not the plate. 'Pass' -> PASS.

insert into public.truck_inspections (
  truck_id, depot_id, checklist_name, result, compliance,
  answers, driver_name, remarks, photographed_issues,
  status, source_meta, created_at, updated_at
)
select t.id, d.id, 'Customer Truck Inspection',
  case when v.result = 'PASS' then 'PASS'::public.truck_result
       else 'FAIL'::public.truck_result end,
  case when v.result = 'PASS' then 100.0 else 50.0 end,
  v.answers::jsonb, v.driver_name, v.remarks, v.photo_paths,
  'SUBMITTED'::public.inspection_status, v.source_meta::jsonb,
  v.created_at::timestamp, v.created_at::timestamp
