) as v(vehicle_id, depot_code, result, driver_name, remarks, photo_paths, created_at, answers, source_meta)
join public.trucks t on t.source_meta->>'vehicle_id' = v.vehicle_id
left join public.depots d on d.code = v.depot_code
on conflict do nothing;

insert into public.truck_inspections (
  truck_id, depot_id, checklist_name, result, compliance,
  answers, driver_name, remarks, photographed_issues,
  status, source_meta, created_at, updated_at
)
select t.id, d.id, 'Customer Truck Inspection',
  case when v.result = 'PASS' then 'PASS'::public.truck_result
       else 'FAIL'::public.truck_result end,
  case when v.result = 'PASS' then 100.0 else 50.0 end,
  v.answers::jsonb, v.driver_name, v.remarks, v.photo_paths,
  'SUBMITTED'::public.inspection_status, v.source_meta::jsonb,
