left join public.depots d on d.code = v.depot_code
on conflict do nothing;

insert into public.truck_inspections (
  truck_id, depot_id, checklist_name, result, compliance,
  answers, driver_name, remarks, photographed_issues,
  status, source_meta, created_at, updated_at
)
